from itertools import combinations
R='ABCDE'; F=[('A','BC'),('CD','E'),('E','A')]
def closure(X):
    X=set(X); ch=True
    while ch:
        ch=False
        for l,r in F:
            if set(l)<=X and not set(r)<=X: X|=set(r); ch=True
    return X
sk=[set(c) for k in range(1,6) for c in combinations(R,k) if closure(c)==set(R)]
ck=sorted(''.join(sorted(s)) for s in sk if not any(t<s for t in sk))
print(ck)  # ['AD', 'CD', 'DE']
for x in ['A','E','D','BD','AD','CD','ED']: print(x, ''.join(sorted(closure(x))))
